<script>
  import { toSentence } from '@splendidlabz/utils'
  import { randomString } from '@splendidlabz/utils/dom'
  import { init } from '../../utils'
  import SVG from '../Icon/Icon.svelte'
  import TextInput from './TextInput.svelte'

  let {
    name: nameProp = '',
    label: labelProp = null,
    value: valueProp = 'on',
    checked = $bindable(false),
    ref = $bindable(null),
    class: klass = '',
    icon = null,
    iconClass = null,
    fieldClass = '',
    labelClass = '',
    id = randomString(8),
    readonly = null,
    disabled = null,
    alwaysSend = false,
    hasInput = false,
    ...rest
  } = $props()

  // Local mutable state initialized from props
  let name = $state('')
  let label = $state(null)
  let value = $state('on')
  let ov = $state('on')

  init(() => {
    name = nameProp
    label = labelProp
    value = valueProp
    ov = valueProp

    // Name and value are often confused. Value should be 'on', but users mistake value as name — swap it for them
    if (value !== 'on' && !name) name = value

    // Safety check
    if (!name) throw new Error('Checkbox requires a name')

    // Create label from name if not provided
    if (name && !label && label !== '') label = toSentence(name)
  })

  $effect(() => {
    // Sends the checked value upwards
    if (checked) value = ov

    // Allows sendAlways to work (I think)
    if (!checked) value = 'off'
  })
</script>

<div class="checkbox {klass}" class:checked class:disabled class:readonly>
  <div class="group">
    <div class="checkmark-container">
      <input
        {...rest}
        bind:this={ref}
        {id}
        {name}
        class="input {fieldClass}"
        disabled={disabled || readonly}
        type="checkbox"
        {value}
        bind:checked
      />

      {#if readonly || alwaysSend}
        <input {name} {checked} type="hidden" {value} />
      {/if}

      {#if icon}
        <SVG class="checkmark {iconClass}" {icon} />
      {:else}
        <svg class="checkmark" fill="none" viewBox="0 0 24 24">
          <path
            d="M5 12L10 17L20 7"
            stroke="currentcolor"
            stroke-linecap="round"
            stroke-linejoin="round"
            stroke-width="3"
          />
        </svg>
      {/if}
    </div>

    {#if label}
      <label class="label {labelClass}" for={id}>{label}</label>
    {/if}
  </div>

  {#if hasInput}
    <TextInput {name} />
  {/if}
</div>
